								event_details.bin = bin;
								event_details.offset = cursor;
								event_details.raw_ptr = raw_ptr;
								event_details.ordinal = ordinal;
								event_details.addend = addend;

								carry_on = callback (context, (RFixupEventDetails *) &event_details);
