	rc = drc_pmem_query_stats(p, stats, 0);
	if (rc)
		goto out;

	/*
	 * Allocate memory and populate nvdimm_event_map.
	 * Allocate an extra element for NULL entry
	 */
	p->nvdimm_events_map = kcalloc(available_events + 1,
				       sizeof(stat->stat_id),
